:root {
  color-scheme: light dark;
  --page: #f5f4ed;
  --surface: #fffefa;
  --surface-soft: #f8f7f0;
  --ink: #242920;
  --muted: #73796e;
  --line: #e4e5d9;
  --accent: #477a46;
  --accent-dark: #315d34;
  --accent-soft: #e8f0dd;
  --orange: #e99456;
  --blue: #e4eef0;
  --danger: #b74746;
  --success: #286d49;
  --shadow: 0 20px 55px rgb(46 57 34 / 8%);
}

@media (prefers-color-scheme: dark) {
  :root {
    --page: #191d18;
    --surface: #252b23;
    --surface-soft: #2e352a;
    --ink: #eff1e8;
    --muted: #b6bdad;
    --line: #414a3b;
    --accent: #a7cf91;
    --accent-dark: #c4e3b0;
    --accent-soft: #344331;
    --orange: #ffb078;
    --blue: #2d4042;
    --danger: #ffaaa0;
    --success: #9ee0b3;
    --shadow: 0 20px 55px rgb(0 0 0 / 24%);
  }
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 34px 20px 60px;
  background:
    radial-gradient(ellipse at 2% 2%, rgb(233 148 86 / 15%), transparent 31rem),
    radial-gradient(ellipse at 96% 29%, rgb(71 122 70 / 12%), transparent 30rem),
    var(--page);
  color: var(--ink);
  font: 16px/1.6 "Avenir Next", Avenir, "Segoe UI", sans-serif;
}

a { color: var(--accent-dark); text-underline-offset: 4px; }
a:hover { color: var(--orange); }
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 3px;
}

.home, .form-page { width: min(100%, 1020px); margin: 0 auto; }
.back { display: inline-flex; align-items: center; gap: 8px; margin-bottom: 30px; font-size: .9rem; font-weight: 750; text-decoration: none; }
.back::before { content: "←"; font-size: 1.1em; }
.eyebrow { margin: 0 0 10px; color: var(--accent-dark); font-size: .72rem; font-weight: 850; letter-spacing: .13em; text-transform: uppercase; }
.live-dot { display: inline-block; width: 8px; height: 8px; margin: 0 6px 1px 0; border-radius: 50%; background: var(--orange); }

.hero { display: grid; grid-template-columns: minmax(0, 1fr) minmax(250px, .8fr); align-items: center; gap: 36px; margin-bottom: 38px; }
.hero-copy { padding: 12px 0; }
h1, h2 { font-family: Georgia, "Times New Roman", serif; font-weight: 500; line-height: 1.12; }
h1 { margin: 0 0 18px; font-size: clamp(3rem, 8vw, 5.2rem); letter-spacing: -.055em; }
h1 span { color: var(--accent); font-style: italic; }
.lede { max-width: 59ch; margin: 0; color: var(--muted); font-size: 1.02rem; }
.hero-link { display: inline-flex; align-items: center; gap: 12px; margin-top: 24px; padding: 12px 17px; border-radius: 10px; background: var(--accent); color: #fff; font-size: .88rem; font-weight: 800; text-decoration: none; transition: transform .18s ease, background .18s ease; }
.hero-link:hover { transform: translateY(-2px); background: var(--accent-dark); color: #fff; }

.hero-art { position: relative; display: grid; min-height: 300px; place-items: center; overflow: hidden; border: 1px solid var(--line); border-radius: 22px; background: var(--accent-soft); }
.art-orbit { position: absolute; width: 218px; height: 218px; border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent); border-radius: 50%; transform: rotate(-28deg) scaleX(1.45); }
.orbit-two { width: 175px; height: 175px; transform: rotate(38deg) scaleX(1.65); border-color: color-mix(in srgb, var(--orange) 65%, transparent); }
.art-sticker { position: relative; z-index: 1; display: flex; width: 136px; height: 136px; flex-direction: column; align-items: center; justify-content: center; gap: 2px; border: 1px solid rgb(255 255 255 / 48%); border-radius: 34px; background: var(--orange); color: #30271f; box-shadow: 0 15px 35px rgb(117 77 41 / 20%); transform: rotate(-8deg); }
.art-sticker span { font-size: .7rem; font-weight: 900; letter-spacing: .18em; }
.art-sticker strong { font-family: Georgia, serif; font-size: 3.2rem; font-weight: 500; line-height: 1; }
.art-label { position: absolute; right: 22px; bottom: 20px; color: var(--accent-dark); font-family: Georgia, serif; font-size: 1rem; font-style: italic; line-height: 1.2; text-align: right; transform: rotate(-5deg); }
.art-star { position: absolute; color: var(--accent); font-size: 1.7rem; }
.star-one { top: 36px; left: 34px; }
.star-two { top: 58px; right: 43px; color: var(--orange); }

.content-panel { padding: clamp(20px, 4vw, 34px); border: 1px solid var(--line); border-radius: 22px; background: var(--surface); box-shadow: var(--shadow); }
.section-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; margin-bottom: 22px; }
.section-heading .eyebrow { margin-bottom: 5px; }
h2 { margin: 0; font-size: clamp(1.45rem, 4vw, 2rem); letter-spacing: -.025em; }
.week-tag { flex: 0 0 auto; padding: 7px 12px; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); font-size: .76rem; font-weight: 750; }
.lesson-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-bottom: 20px; }
.lesson { padding: 17px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface-soft); }
.lesson-icon { display: grid; width: 34px; height: 34px; margin-bottom: 13px; place-items: center; border-radius: 11px; background: var(--accent-soft); color: var(--accent-dark); font-weight: 850; }
.lesson-icon-orange { background: color-mix(in srgb, var(--orange) 22%, var(--surface)); color: #9b542b; }
.lesson-icon-blue { background: var(--blue); color: var(--accent-dark); }
.lesson h3 { margin: 0; font-size: .95rem; }
.lesson p { margin: 6px 0 0; color: var(--muted); font-size: .82rem; line-height: 1.5; }
.lab-row { display: grid; grid-template-columns: 42px minmax(0, 1fr) auto; align-items: center; gap: 14px; padding: 15px 16px; border: 1px solid var(--line); border-radius: 13px; background: var(--accent-soft); color: var(--ink); text-decoration: none; transition: border-color .18s ease, transform .18s ease; }
.lab-row:hover { transform: translateY(-2px); border-color: var(--accent); color: var(--ink); }
.lab-number { display: grid; width: 38px; height: 38px; place-items: center; border-radius: 11px; background: var(--surface); color: var(--accent-dark); font-size: .76rem; font-weight: 850; }
.lab-copy strong, .lab-copy small { display: block; }
.lab-copy strong { font-size: .94rem; }
.lab-copy small { margin-top: 2px; color: var(--muted); font-size: .78rem; }
.lab-arrow { color: var(--accent-dark); font-size: 1.25rem; }
.page-note { margin: 17px 4px 0; color: var(--muted); font-size: .83rem; }

.form-layout { display: grid; grid-template-columns: minmax(255px, .8fr) minmax(0, 1.2fr); overflow: hidden; border: 1px solid var(--line); border-radius: 22px; background: var(--surface); box-shadow: var(--shadow); }
.form-aside { position: relative; display: flex; min-height: 100%; flex-direction: column; justify-content: space-between; overflow: hidden; padding: clamp(25px, 5vw, 42px); background: #477a46; color: #fffef7; }
.form-aside::after { position: absolute; right: -100px; bottom: -132px; width: 310px; height: 310px; border: 1px solid rgb(255 255 255 / 28%); border-radius: 50%; box-shadow: 0 0 0 34px rgb(255 255 255 / 7%), 0 0 0 70px rgb(255 255 255 / 5%); content: ""; }
.aside-content, .aside-bottom { position: relative; z-index: 1; }
.aside-kicker { margin: 0 0 15px; color: rgb(255 255 255 / 76%); font-size: .72rem; font-weight: 850; letter-spacing: .14em; text-transform: uppercase; }
.form-aside h2 { max-width: 9ch; color: #fffef7; font-size: clamp(2.2rem, 4vw, 3.3rem); }
.aside-copy { max-width: 32ch; margin: 14px 0 0; color: rgb(255 255 255 / 80%); font-size: .92rem; }
.aside-bottom { display: flex; align-items: center; gap: 10px; margin-top: 45px; color: rgb(255 255 255 / 78%); font-size: .77rem; }
.aside-dots { display: flex; gap: 5px; }
.aside-dots span { width: 6px; height: 6px; border-radius: 50%; background: #fffef7; opacity: .7; }
.aside-dots span:first-child { opacity: 1; }
.form-main { padding: clamp(24px, 5vw, 44px); }
.form-main h1 { margin: 0; font-size: clamp(2rem, 5vw, 2.8rem); letter-spacing: -.04em; }
.form-intro { margin: 7px 0 24px; color: var(--muted); font-size: .9rem; }
.form-section { margin: 0 0 20px; padding: 0; border: 0; }
.form-section legend { width: 100%; margin-bottom: 12px; padding-bottom: 9px; border-bottom: 1px solid var(--line); color: var(--accent-dark); font-size: .73rem; font-weight: 850; letter-spacing: .1em; text-transform: uppercase; }
.field { margin-bottom: 13px; }
.field-row { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.field label { display: block; margin-bottom: 5px; color: var(--ink); font-size: .8rem; font-weight: 750; }
.field input, .field select { display: block; width: 100%; min-height: 46px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface-soft); color: var(--ink); font: inherit; font-size: .86rem; transition: border-color .18s ease, box-shadow .18s ease, background .18s ease; }
.field input::placeholder { color: var(--muted); opacity: .8; }
.field input:focus, .field select:focus { border-color: var(--accent); outline: 0; box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 17%, transparent); }
.field input.is-valid, .field select.is-valid { border-color: var(--success); background: color-mix(in srgb, var(--success) 6%, var(--surface)); }
.field input.is-invalid, .field select.is-invalid { border-color: var(--danger); background: color-mix(in srgb, var(--danger) 6%, var(--surface)); }
.error-msg { min-height: 0; margin: 0; color: var(--danger); font-size: .74rem; line-height: 1.35; }
.error-msg:not(:empty) { min-height: 18px; margin-top: 4px; }
.checkbox-wrap { display: flex; align-items: flex-start; gap: 9px; margin: 3px 0 18px; }
.checkbox-wrap input { flex: 0 0 auto; width: 17px; height: 17px; margin: 2px 0 0; accent-color: var(--accent); cursor: pointer; }
.checkbox-wrap label { color: var(--muted); font-size: .8rem; line-height: 1.45; cursor: pointer; }
.terms-error { margin: -13px 0 13px 26px; }
.submit-button { display: flex; width: 100%; min-height: 48px; align-items: center; justify-content: center; gap: 9px; padding: 11px 16px; border: 0; border-radius: 10px; background: var(--accent); color: #fff; font: inherit; font-size: .9rem; font-weight: 800; cursor: pointer; transition: transform .18s ease, background .18s ease; }
.submit-button:hover { transform: translateY(-2px); background: var(--accent-dark); }
.submit-button span { font-size: 1.1em; }
.form-footnote { margin: 13px 0 0; color: var(--muted); font-size: .74rem; text-align: center; }
.success-card { padding: clamp(26px, 5vw, 42px); border: 1px solid var(--line); border-radius: 20px; background: var(--surface); box-shadow: var(--shadow); text-align: center; }
.success-mark { display: grid; width: 58px; height: 58px; margin: 0 auto 17px; place-items: center; border-radius: 19px; background: var(--accent-soft); color: var(--success); font-size: 1.65rem; font-weight: 800; }
.success-card h1 { margin: 0; font-size: clamp(2rem, 6vw, 3rem); }
.success-card > p { margin: 8px auto 23px; color: var(--muted); }
.summary-box { display: grid; gap: 0; margin: 0 0 22px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface-soft); text-align: left; }
.summary-row { display: flex; justify-content: space-between; gap: 16px; padding: 11px 14px; border-bottom: 1px solid var(--line); font-size: .84rem; }
.summary-row:last-child { border-bottom: 0; }
.summary-row dt { color: var(--muted); }
.summary-row dd { margin: 0; color: var(--ink); font-weight: 750; text-align: right; overflow-wrap: anywhere; }
.reset-button { min-height: 42px; padding: 9px 15px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface); color: var(--accent-dark); font: inherit; font-size: .84rem; font-weight: 750; cursor: pointer; }
.reset-button:hover { border-color: var(--accent); background: var(--accent-soft); }
[hidden] { display: none !important; }

@media (max-width: 760px) {
  body { padding: 24px 14px 42px; }
  .hero { grid-template-columns: 1fr; gap: 24px; }
  .hero-art { min-height: 245px; }
  .lesson-grid { grid-template-columns: 1fr; }
  .lesson { display: grid; grid-template-columns: 38px 1fr; column-gap: 12px; align-items: center; }
  .lesson-icon { grid-row: span 2; margin: 0; }
  .lesson p { margin-top: 2px; }
  .form-layout { grid-template-columns: 1fr; }
  .form-aside { min-height: 235px; }
  .aside-bottom { margin-top: 30px; }
}

@media (max-width: 480px) {
  .section-heading { align-items: flex-start; flex-direction: column; }
  .field-row { grid-template-columns: 1fr; gap: 0; }
  .form-main { padding: 23px 18px; }
  .lab-row { grid-template-columns: 38px minmax(0, 1fr) auto; gap: 10px; padding: 12px; }
  .lab-copy small { font-size: .72rem; }
  .summary-row { flex-direction: column; gap: 2px; }
  .summary-row dd { text-align: left; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; }
}
